package practice.e;

import java.math.BigDecimal;
import java.time.Instant;

// TODO: make this a JPA entity on table "meter_reading" with an index on (meterId, readAt).
// TODO: Long id generated by the database (IDENTITY); meterId: not null, length 40; kwh: not null, precision 12 scale 3; readAt: not null.
// TODO: JPA needs a no-arg constructor: which visibility is enough, and why not public?
public class MeterReading {
    private Long id;
    private String meterId;
    private BigDecimal kwh;
    private Instant readAt;

    public MeterReading(String meterId, BigDecimal kwh, Instant readAt) {
        this.meterId = meterId;
        this.kwh = kwh;
        this.readAt = readAt;
    }

    public Long getId() { return id; }
    public String getMeterId() { return meterId; }
    public BigDecimal getKwh() { return kwh; }
    public Instant getReadAt() { return readAt; }
}
